package com.comfyremote.app.data.project

import android.media.MediaMetadataRetriever
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import java.io.File
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeout
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Real device/emulator media pipeline regression, with deterministic inputs
 * generated by tools/qa_audio_mix_fixture.sh (no paid network calls).
 *
 * Checks a mixed audio+video export actually passes Media3/MediaCodec and
 * contains both tracks. The companion host script also measures 440 Hz
 * source audio and 880 Hz overlay audio in the resulting PCM.
 */
@RunWith(AndroidJUnit4::class)
class StudioAudioExportInstrumentedTest {

    @Test
    fun media3ExportsOriginalAndOverlayAudioInParallel() = runBlocking {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val video = File(context.filesDir, "qa-source.mp4")
        val overlay = File(context.filesDir, "qa-overlay.wav")
        assertTrue("QA video fixture missing", video.isFile && video.length() > 0)
        assertTrue("QA audio fixture missing", overlay.isFile && overlay.length() > 0)

        val timeline = Timeline(
            videoTrack = listOf(TimelineClip(
                id = "fixture-video", sourcePath = video.absolutePath,
                sourceOutMs = 1800, volume = 1f,
            )),
            audioTrack = listOf(TimelineClip(
                id = "fixture-audio", sourcePath = overlay.absolutePath,
                sourceOutMs = 1800, volume = 1f,
            )),
        )
        val plan = ExportPlanBuilder.build(
            timeline,
            existingPaths = setOf(video.absolutePath, overlay.absolutePath),
            sourceDurationsMs = mapOf(video.absolutePath to 2000L, overlay.absolutePath to 2000L),
        )
        assertEquals(1, plan.items.size)
        assertEquals(1, plan.audioItems.size)
        val tmp = File(context.filesDir, "qa-export.mp4.tmp")
        tmp.delete()
        val result = withContext(Dispatchers.Main) {
            withTimeout(120_000L) {
                VideoExporter(context).export(plan, tmp) { }
            }
        }
        assertTrue("Transformer did not finish", result is VideoExporter.Result.Success)
        assertTrue("Missing encoded output", tmp.isFile && tmp.length() > 0)
        val final = File(context.filesDir, "qa-export.mp4")
        final.delete()
        assertTrue("Export rename failed", tmp.renameTo(final))

        val retriever = MediaMetadataRetriever()
        try {
            retriever.setDataSource(final.absolutePath)
            assertEquals("yes", retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO))
            assertEquals("yes", retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO))
            val ms = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)!!.toLong()
            assertTrue("Unexpected movie duration: ${ms}ms", ms in 1450..2100)
        } finally {
            retriever.release()
        }
    }
}
